// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WebDAVCredential) predicate.WebDAVCredential {
	return predicate.WebDAVCredential(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WebDAVCredential) predicate.WebDAVCredential {
	return predicate.WebDAVCredential(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WebDAVCredential) predicate.WebDAVCredential {
	return predicate.WebDAVCredential(sql.NotPredicates(p))
}
